typedef float time_value_t;

struct input_device_vtable
{
    char padding[0x48];
    short adjustment;
    short padding2;
    bool (*is_connected)(void *);
};

class input_device
{
    char padding[4];
    input_device_vtable *vtable;

public:
    bool is_connected()
    {
        input_device_vtable *table = vtable;
        return table->is_connected((char *)this + table->adjustment);
    }
};

class input_mgr
{
    char padding[0x28];
    input_device *joysticks[4];

public:
    static input_mgr *inst();
    input_device *get_joystick_index(int index) { return joysticks[index]; }
};

__asm__(".equ input_manager, 0x0045B7B0");
extern input_mgr *input_manager;
inline input_mgr *input_mgr::inst() { return input_manager; }

struct menu_entry_vtable
{
    char padding[0x28];
    short adjustment;
    short padding2;
    void (*disable)(void *, bool);
};

class FEMenuEntry
{
    char padding[0x60];
    menu_entry_vtable *vtable;

public:
    void Disable(bool disabled)
    {
        menu_entry_vtable *table = vtable;
        table->disable((char *)this + table->adjustment, disabled);
    }
};

struct menu_vtable
{
    char padding[0x18];
    short adjustment;
    short padding2;
    void (*set_high)(void *, FEMenuEntry *, bool);
};

class FEMenu
{
    char padding0[0x4c];

protected:
    FEMenuEntry *highlighted;

private:
    char padding1[0x24];
    menu_vtable *vtable;

protected:
    void setHigh(FEMenuEntry *entry, bool anim = true)
    {
        menu_vtable *table = vtable;
        table->set_high((char *)this + table->adjustment, entry, anim);
    }

public:
    void Update(time_value_t time_inc);
};

__asm__(".equ Update__6FEMenuf, 0x00156DC8");

class MultiControllerMenu : public FEMenu
{
public:
    enum
    {
        MultiOneEntry,
        MultiTwoEntry,
        MultiEnd
    };

    FEMenuEntry *entry[MultiEnd];

    void Update(time_value_t time_inc);
};

void MultiControllerMenu::Update(time_value_t time_inc)
{
    int num_controllers = 0;

    for (int j = 0; j < 4; j++)
    {
        input_device *joy = input_mgr::inst()->get_joystick_index(j);
        if (joy && joy->is_connected())
            num_controllers++;
    }

    if (num_controllers >= 2)
    {
        entry[MultiOneEntry]->Disable(false);
        entry[MultiTwoEntry]->Disable(false);
    }
    else
    {
        if (highlighted == entry[MultiTwoEntry])
            setHigh(entry[MultiOneEntry]);
        entry[MultiOneEntry]->Disable(false);
        entry[MultiTwoEntry]->Disable(true);
    }

    FEMenu::Update(time_inc);
}
